using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class UnitEffectsJoystickInput : BaseJoystickInput
{
	[Header("Components")]
	[SerializeField]
	private UnitEffects unitEffects;

	[SerializeField]
	private int effectInstanceAmountPerLine = 4;

	[ShowNonSerializedField]
	private int currentEffectInstanceIndex;

	[ShowNonSerializedField]
	private int currentRowIndex;

	[ShowNonSerializedField]
	private bool unitDetailJoystickInputOn;

	private UnitDetailJoystickInput unitDetailJoystickInput;

	private bool hasUnitDetailJoystickInput;

	private DicePreviewJoystickInput dicePreviewJoystickInputCompanion;

	public bool UnitHasDetail
	{
		get
		{
			if (!unitHasAtLeastOneEffect)
			{
				return hasUnitDetailJoystickInput;
			}
			return true;
		}
	}

	private bool unitHasAtLeastOneEffect => unitEffects.activeEffectsList.Count > 0;

	public int CurrentEffectInstanceIndex => currentEffectInstanceIndex;

	public DicePreviewJoystickInput DicePreviewJoystickInputCompanion => dicePreviewJoystickInputCompanion;

	protected override ZoomableInstance GetCurrentZoomableInstance()
	{
		return unitEffects.activeEffectsList[currentEffectInstanceIndex];
	}

	public void InitializeUnitDetailJoystickInput(UnitDetailJoystickInput unitDetailJoystickInput)
	{
		this.unitDetailJoystickInput = unitDetailJoystickInput;
		hasUnitDetailJoystickInput = unitDetailJoystickInput != null;
	}

	public void EnableInput(DicePreviewJoystickInput dicePreviewJoystickInputCompanion = null)
	{
		currentEffectInstanceIndex = 0;
		currentRowIndex = 0;
		unitDetailJoystickInputOn = false;
		this.dicePreviewJoystickInputCompanion = dicePreviewJoystickInputCompanion;
		if (hasUnitDetailJoystickInput)
		{
			if (unitHasAtLeastOneEffect)
			{
				CurrentZoomableInstanceOnMouseOverExit(value: true);
			}
			else
			{
				unitDetailJoystickInput.GoToCharacterDetail();
				unitDetailJoystickInputOn = true;
			}
		}
		else
		{
			CurrentZoomableInstanceOnMouseOverExit(value: true);
		}
		base.enabled = true;
	}

	private void Update()
	{
		if (base.inputManager.IsPauseOrIsJoystickNotBeingUsed() || !base.inputManager.GetAxisInput())
		{
			return;
		}
		if (unitDetailJoystickInputOn)
		{
			if (base.inputManager.GetVerticalAxisDown())
			{
				if (unitHasAtLeastOneEffect)
				{
					unitDetailJoystickInput.DisableCharacterDetail();
					CurrentZoomableInstanceOnMouseOverExit(value: true);
					unitDetailJoystickInputOn = false;
				}
				else
				{
					unitDetailJoystickInput.AxisDownInput();
				}
			}
			else if (base.inputManager.GetVerticalAxisUp())
			{
				unitDetailJoystickInput.AxisUpInput();
			}
			else if (base.inputManager.GetHorizontalAxisLeft())
			{
				unitDetailJoystickInput.AxisLeftInput();
			}
			else if (base.inputManager.GetHorizontalAxisRight())
			{
				unitDetailJoystickInput.AxisRightInput();
			}
			return;
		}
		bool flag = true;
		CurrentZoomableInstanceOnMouseOverExit(value: false);
		if (base.inputManager.GetHorizontalAxisLeft())
		{
			currentEffectInstanceIndex--;
		}
		else if (base.inputManager.GetHorizontalAxisRight())
		{
			currentEffectInstanceIndex++;
		}
		else if (base.inputManager.GetVerticalAxisDown())
		{
			if (currentRowIndex < RowIndexAmount() - 1)
			{
				int rowIndexModifier = GetRowIndexModifier();
				currentRowIndex++;
				currentEffectInstanceIndex += GetRowIndexModifier() - rowIndexModifier;
			}
		}
		else if (base.inputManager.GetVerticalAxisUp())
		{
			if (currentRowIndex > 0)
			{
				currentRowIndex--;
				currentEffectInstanceIndex -= effectInstanceAmountPerLine;
			}
			else if (currentRowIndex == 0)
			{
				if (dicePreviewJoystickInputCompanion != null)
				{
					DicePreviewJoystickInputToggleUpdateDicePreview();
					flag = false;
					DisableInput();
				}
				else if (hasUnitDetailJoystickInput)
				{
					unitDetailJoystickInput.GoToCharacterDetail();
					unitDetailJoystickInputOn = true;
				}
			}
		}
		if (!unitDetailJoystickInputOn)
		{
			currentEffectInstanceIndex = Mathf.Clamp(currentEffectInstanceIndex, 0, unitEffects.activeEffectsList.Count - 1);
			if (flag)
			{
				CurrentZoomableInstanceOnMouseOverExit(value: true);
			}
		}
	}

	private int GetRowIndexModifier()
	{
		return currentRowIndex * effectInstanceAmountPerLine;
	}

	private int RowIndexAmount()
	{
		return unitEffects.activeEffectsList.Count / effectInstanceAmountPerLine + 1;
	}

	public void DisableInput()
	{
		if (unitDetailJoystickInputOn)
		{
			unitDetailJoystickInput.DisableCharacterDetail();
		}
		else if (currentEffectInstanceIndex >= 0 && unitHasAtLeastOneEffect)
		{
			CurrentZoomableInstanceOnMouseOverExit(value: false);
		}
		base.enabled = false;
	}

	public void DicePreviewJoystickInputToggleUpdateDicePreview()
	{
		if (dicePreviewJoystickInputCompanion != null)
		{
			dicePreviewJoystickInputCompanion.ToggleUpdateDicePreviewJoystickInput(toggle: true);
		}
		dicePreviewJoystickInputCompanion = null;
	}

	public override void OnAfterOptionPressed()
	{
		if (unitHasAtLeastOneEffect)
		{
			CurrentZoomableInstanceOnMouseOverExit(value: false);
		}
	}

	public override void OnAfterResumePressed()
	{
		if (unitHasAtLeastOneEffect)
		{
			CurrentZoomableInstanceOnMouseOverExit(value: true);
		}
	}
}
